func voltPostFlagScan(r rt.Row) (PostFlag, error) {
	var voltV PostFlag
	voltErr := r.Scan(&voltV.ID, &voltV.Reviewed, &voltV.Approved)
	return voltV, rt.Refused("PostFlag", voltErr)
}

func voltPostFlagValues(voltR PostFlag) []any { return []any{voltR.ID, voltR.Reviewed, voltR.Approved} }

func voltPostFlagApply(voltData, voltVals PostFlag, voltSet []bool) PostFlag {
	voltR := voltData
	if voltSet[1] {
		voltR.Reviewed = voltVals.Reviewed
	}
	if voltSet[2] {
		voltR.Approved = voltVals.Approved
	}
	return voltR
}

func voltPostFlagCast(c rt.Changeset[PostFlag], p rt.Params[PostFlag], i int) (rt.Changeset[PostFlag], error) {
	switch i {
	case 1:
		voltV, voltOK, voltErr := rt.Field(p, "reviewed", "pay.YesNo", false, func(voltR *PostFlag) pay.YesNo { return voltR.Reviewed })
		if voltErr != nil || !voltOK {
			return c, voltErr
		}
		return PostFlagChangeset{c}.ReviewedSet(voltV).Changeset, nil
	case 2:
		voltV, voltOK, voltErr := rt.Field(p, "approved", "pay.YesNo", true, func(voltR *PostFlag) rt.Null[pay.YesNo] { return voltR.Approved })
		if voltErr != nil || !voltOK {
			return c, voltErr
		}
		return PostFlagChangeset{c}.ApprovedSet(voltV).Changeset, nil
	}
	return c, nil
}
